from bisect import bisect_right


def regex_search(pattern: str, text: str) -> bool:
    def _parse_pattern(p: str):
        ast, pos = _parse_alt(p, 0, None)
        if pos != len(p):
            raise ValueError
        return ast

    def _parse_alt(p: str, pos: int, close):
        alternatives = []
        while True:
            alt, pos = _parse_seq(p, pos, close)
            alternatives.append(alt)
            if pos < len(p) and p[pos] == '|':
                pos += 1
                continue
            break

        if len(alternatives) == 1:
            return alternatives[0], pos
        return ('alt', alternatives), pos

    def _parse_seq(p: str, pos: int, close):
        children = []
        prev = 'none'

        while pos < len(p) and p[pos] != '|' and p[pos] != ')':
            if p[pos] in '*+?':
                if prev == 'none' or prev == 'anchor' or prev == 'quant':
                    raise ValueError

            ast, pos, prev_base = _parse_element(p, pos, close)

            if pos < len(p) and p[pos] in '*+?':
                if prev_base == 'anchor':
                    raise ValueError
                op = p[pos]
                pos += 1
                ast = ('quant', op, ast)
                prev = 'quant'
            else:
                prev = prev_base

            children.append(ast)

        return ('concat', children), pos

    def _parse_element(p: str, pos: int, close):
        if pos >= len(p):
            raise ValueError

        c = p[pos]

        if c == '(':
            pos += 1
            ast, pos = _parse_alt(p, pos, ')')
            if pos >= len(p) or p[pos] != ')':
                raise ValueError
            pos += 1
            return ('group', ast), pos, 'element'

        if c == '[':
            ast, pos = _parse_class(p, pos)
            return ast, pos, 'element'

        if c == '^':
            return ('assert', 'start'), pos + 1, 'anchor'

        if c == '$':
            return ('assert', 'end'), pos + 1, 'anchor'

        if c == '.':
            return ('dot',), pos + 1, 'element'

        if c == '\\':
            if pos + 1 >= len(p):
                raise ValueError
            return ('lit', ord(p[pos + 1])), pos + 2, 'element'

        return ('lit', ord(c)), pos + 1, 'element'

    def _parse_class(p: str, pos: int):
        pos += 1
        negate = False

        if pos < len(p) and p[pos] == '^':
            negate = True
            pos += 1

        if pos >= len(p):
            raise ValueError
        if p[pos] == ']':
            raise ValueError

        ranges = []

        while pos < len(p):
            if p[pos] == ']':
                pos += 1
                return ('class', ranges, negate), pos

            if p[pos] == '\\':
                if pos + 1 >= len(p):
                    raise ValueError
                x = p[pos + 1]
                pos += 2
            else:
                x = p[pos]
                pos += 1

            if (
                pos < len(p)
                and p[pos] == '-'
                and pos + 1 < len(p)
                and p[pos + 1] != ']'
            ):
                pos += 1

                if pos >= len(p):
                    raise ValueError

                if p[pos] == '\\':
                    if pos + 1 >= len(p):
                        raise ValueError
                    y = p[pos + 1]
                    pos += 2
                else:
                    y = p[pos]
                    pos += 1

                lx, ly = ord(x), ord(y)
                if lx > ly:
                    raise ValueError
                ranges.append((lx, ly))
            else:
                lx = ord(x)
                ranges.append((lx, lx))

        raise ValueError

    def _merge_ranges(ranges):
        if not ranges:
            raise ValueError

        ranges.sort()
        merged = []
        cur_lo, cur_hi = ranges[0]

        for lo, hi in ranges[1:]:
            if lo <= cur_hi + 1:
                if hi > cur_hi:
                    cur_hi = hi
            else:
                merged.append((cur_lo, cur_hi))
                cur_lo, cur_hi = lo, hi

        merged.append((cur_lo, cur_hi))
        return merged

    def _compile_to_nfa(ast):
        eps_uncond = []
        eps_start = []
        eps_end = []
        consume = []

        def new_state():
            eps_uncond.append([])
            eps_start.append([])
            eps_end.append([])
            consume.append(None)
            return len(consume) - 1

        def add_eps(u, v, kind):
            if kind == 0:
                eps_uncond[u].append(v)
            elif kind == 1:
                eps_start[u].append(v)
            else:
                eps_end[u].append(v)

        def add_consume(u, v, kind, data):
            consume[u] = (v, kind, data)

        def compile(node):
            typ = node[0]

            if typ == 'empty':
                s = new_state()
                return s, s

            if typ == 'lit':
                s = new_state()
                a = new_state()
                add_consume(s, a, 0, node[1])
                return s, a

            if typ == 'dot':
                s = new_state()
                a = new_state()
                add_consume(s, a, 1, None)
                return s, a

            if typ == 'class':
                ranges = _merge_ranges(node[1])
                negate = node[2]
                lo = [l for l, _ in ranges]
                hi = [h for _, h in ranges]
                s = new_state()
                a = new_state()
                add_consume(s, a, 2, (lo, hi, negate))
                return s, a

            if typ == 'assert':
                kind = 1 if node[1] == 'start' else 2
                s = new_state()
                a = new_state()
                add_eps(s, a, kind)
                return s, a

            if typ == 'group':
                return compile(node[1])

            if typ == 'concat':
                if not node[1]:
                    s = new_state()
                    return s, s

                start, accept = compile(node[1][0])
                for child in node[1][1:]:
                    next_start, next_accept = compile(child)
                    add_eps(accept, next_start, 0)
                    accept = next_accept
                return start, accept

            if typ == 'alt':
                if not node[1]:
                    s = new_state()
                    return s, s

                if len(node[1]) == 1:
                    return compile(node[1][0])

                start = new_state()
                accept = new_state()

                for child in node[1]:
                    child_start, child_accept = compile(child)
                    add_eps(start, child_start, 0)
                    add_eps(child_accept, accept, 0)

                return start, accept

            if typ == 'quant':
                op = node[1]
                inner_start, inner_accept = compile(node[2])
                start = new_state()
                accept = new_state()

                if op == '*':
                    add_eps(start, inner_start, 0)
                    add_eps(start, accept, 0)
                    add_eps(inner_accept, inner_start, 0)
                    add_eps(inner_accept, accept, 0)
                elif op == '+':
                    add_eps(start, inner_start, 0)
                    add_eps(inner_accept, inner_start, 0)
                    add_eps(inner_accept, accept, 0)
                else:  # '?'
                    add_eps(start, inner_start, 0)
                    add_eps(start, accept, 0)
                    add_eps(inner_accept, accept, 0)

                return start, accept

            raise ValueError

        start, accept = compile(ast)
        return start, accept, eps_uncond, eps_start, eps_end, consume

    ast = _parse_pattern(pattern)
    start_state, accept_state, eps_uncond, eps_start, eps_end, consume = _compile_to_nfa(ast)

    n = len(text)
    state_count = len(consume)
    seen_stamp = [0] * state_count
    stamp = 0

    def closure(states, pos):
        nonlocal stamp
        stamp += 1
        seen = []
        stack = []
        found_accept = False

        for s in states:
            if seen_stamp[s] != stamp:
                seen_stamp[s] = stamp
                seen.append(s)
                stack.append(s)
                if s == accept_state:
                    found_accept = True

        while stack and not found_accept:
            u = stack.pop()

            for v in eps_uncond[u]:
                if seen_stamp[v] != stamp:
                    seen_stamp[v] = stamp
                    seen.append(v)
                    stack.append(v)
                    if v == accept_state:
                        found_accept = True

            if pos == 0:
                for v in eps_start[u]:
                    if seen_stamp[v] != stamp:
                        seen_stamp[v] = stamp
                        seen.append(v)
                        stack.append(v)
                        if v == accept_state:
                            found_accept = True

            if pos == n:
                for v in eps_end[u]:
                    if seen_stamp[v] != stamp:
                        seen_stamp[v] = stamp
                        seen.append(v)
                        stack.append(v)
                        if v == accept_state:
                            found_accept = True

        return seen, found_accept

    active, found = closure([start_state], 0)
    if found:
        return True

    for i, ch in enumerate(text):
        code = ord(ch)
        raw = [start_state]
        append = raw.append

        for s in active:
            trans = consume[s]
            if trans is None:
                continue

            target, kind, data = trans

            if kind == 0:
                if data == code:
                    append(target)
            elif kind == 1:
                append(target)
            else:
                lo, hi, negate = data
                j = bisect_right(lo, code) - 1
                inside = j >= 0 and hi[j] >= code
                if (not inside) if negate else inside:
                    append(target)

        active, found = closure(raw, i + 1)
        if found:
            return True

    return False
